5	test('createInvoice creates a draft invoice with one line', () => {
6	  const r = createInvoice({
7	    customerId: 'C-001',
8	    issueDate: '2026-10-07',
9	    lines: [{ sku: 'DES-HOUR', qty: 5 }],
10	  });
11	  assert.equal(r.ok, true);
12	  const inv = r.value;
13	  assert.equal(inv.customerId, 'C-001');
14	  assert.equal(inv.issueDate, '2026-10-07');
15	  assert.equal(inv.status, 'draft');
16	  assert.equal(inv.lines.length, 1);
17	  assert.equal(inv.lines[0].sku, 'DES-HOUR');
18	  assert.equal(inv.lines[0].name, 'Design work (hour)');
19	  assert.equal(inv.lines[0].qty, 5);
20	  assert.equal(inv.lines[0].unitPrice, 8500);
21	  assert.equal(inv.lines[0].vatRate, 21);
22	});
23	
24	test('createInvoice creates invoices with multiple lines', () => {
25	  const r = createInvoice({
26	    customerId: 'C-002',
27	    issueDate: '2026-10-07',
28	    lines: [
29	      { sku: 'DES-HOUR', qty: 5 },
30	      { sku: 'DEV-HOUR', qty: 3 },
31	    ],
32	  });
33	  assert.equal(r.ok, true);
34	  assert.equal(r.value.lines.length, 2);
35	  assert.equal(r.value.lines[0].name, 'Design work (hour)');
36	  assert.equal(r.value.lines[1].name, 'Development (hour)');
37	});
38	
39	test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
40	  const r = createInvoice({
41	    customerId: 'C-999',
42	    issueDate: '2026-10-07',
43	    lines: [{ sku: 'DES-HOUR', qty: 5 }],
44	  });
45	  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
46	});
47	
48	test('createInvoice reports DATE_INVALID for bad format', () => {
49	  const r = createInvoice({
50	    customerId: 'C-001',
51	    issueDate: '10-07-2026',
52	    lines: [{ sku: 'DES-HOUR', qty: 5 }],
53	  });
54	  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
55	});
56	
57	test('createInvoice reports DATE_INVALID for non-existent dates', () => {
58	  // February 30 doesn't exist
59	  const r = createInvoice({
