test('addLine adds a new line to an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = addLine(inv, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  const inv2 = r2.value;
  assert.equal(inv2.lines.length, 2);
  assert.equal(inv2.lines[1].sku, 'DEV-HOUR');
  assert.equal(inv2.lines[1].qty, 3);
  assert.equal(inv2.lines[1].unitPrice, 9500);
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = addLine(inv, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  const inv2 = r2.value;
  assert.equal(inv2.lines.length, 1);
  assert.equal(inv2.lines[0].qty, 8);
});

test('addLine reports QTY_INVALID', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
